INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ALCHEMY','Western Alchemical Era',1200,1700)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_JUNG_PSYCH_ALCHEMY','secondary scholarship','C. G. Jung, Psychology and Alchemy (Collected Works vol. 12, 1944/1968)','Symbolic and psychological interpretation of the alchemical principles, the coniunctio, Rebis, Sol/Luna, and Mercurius.'),
 ('SRC_ABRAHAM_ALCH_IMAGERY','secondary scholarship','Lyndy Abraham, A Dictionary of Alchemical Imagery (Cambridge University Press, 1998)','Standard reference glossing the tria prima, Green Lion, Azoth, King/Queen, Rebis and other personified alchemical images from the primary corpus.')
INSERT INTO _e VALUES
 ('ENT_ALC_PRINCIPLES','The Alchemical Principles','Abstract power/category','collective','Alchemical','alchemy; transmutation; Hermetic philosophy','B','Collective hub for the personified principles of Western alchemy as engaged operatively and contemplatively within Hermetic-alchemical practice; basis for membership grouping, not a worshipped deity.'),
 ('ENT_ALC_SULPHUR','Sulphur (Philosophical)','Abstract/cosmological category','principle','Alchemical','active masculine principle; soul; combustibility','B','Philosophical Sulphur, the hot/dry active ''masculine'' soul-principle of the tria prima; treated in alchemical practice as the fixing, coloring agent, distinct from common brimstone.'),
 ('ENT_ALC_MERCURY_PHIL','Philosophical Mercury','Abstract/cosmological category','principle','Alchemical','mediating principle; spirit; volatility; transformation','B','Mercurius philosophorum, the volatile mediating spirit-principle of the tria prima and chief agent of transmutation; revered in the corpus as the duplex/ambivalent Mercurius, not ordinary quicksilver. Homonym: distinct from the Roman god Mercury and from Hermes Trismegistus.'),
 ('ENT_ALC_SALT','Salt (Philosophical)','Abstract/cosmological category','principle','Alchemical','passive principle; body; fixity','B','Philosophical Salt, the fixed corporeal ''body'' principle of the Paracelsian tria prima that binds Sulphur and Mercury; an operative category of the practiced art.'),
 ('ENT_ALC_KING','The Alchemical King (Sol/Rex)','Abstract/cosmological category','principle','Alchemical','solar principle; gold; the fixed masculine','B','The Red King / Sol, solar ''masculine'' partner of the royal pair whose union (the chymical wedding) is enacted symbolically in the alchemical opus.'),
 ('ENT_ALC_QUEEN','The Alchemical Queen (Luna/Regina)','Abstract/cosmological category','principle','Alchemical','lunar principle; silver; the volatile feminine','B','The White Queen / Luna, lunar ''feminine'' partner of the royal pair in the chymical wedding; counterpart of the King in the practiced coniunctio.'),
 ('ENT_ALC_REBIS','The Rebis','Abstract/cosmological category','principle','Alchemical','coniunctio; hermaphrodite; union of opposites','B','The Rebis, the conjoined hermaphroditic offspring of the King and Queen embodying the union of opposites (coniunctio); a central goal-image of the alchemical work.'),
 ('ENT_ALC_AZOTH','Azoth','Abstract/cosmological category','principle','Alchemical','universal solvent; first matter; transforming agent','B','Azoth, the universal transforming agent/first-and-last principle of the work, often identified with Philosophical Mercury; a key operative term of the practiced art (Paracelsus, Basil Valentine).'),
 ('ENT_ALC_GREEN_LION','The Green Lion','Abstract/cosmological category','principle','Alchemical','crude prime matter; vitriol; dissolution','B','The Green Lion, personified raw/unripe matter or vitriol that ''devours the sun'' (dissolves gold) early in the opus; a recurrent emblematic figure of the alchemical corpus.');
