INSERT INTO _r VALUES
 ('ENT_ALC_SULPHUR','member_of','ENT_ALC_PRINCIPLES','high','Philosophical Sulphur is one of the tria prima grouped under the Alchemical Principles hub.'),
 ('ENT_ALC_MERCURY_PHIL','member_of','ENT_ALC_PRINCIPLES','high','Philosophical Mercury is one of the tria prima grouped under the hub.'),
 ('ENT_ALC_SALT','member_of','ENT_ALC_PRINCIPLES','high','Philosophical Salt completes the Paracelsian tria prima under the hub.'),
 ('ENT_ALC_KING','member_of','ENT_ALC_PRINCIPLES','high','The Alchemical King is a personified principle in the corpus, grouped under the hub.'),
 ('ENT_ALC_QUEEN','member_of','ENT_ALC_PRINCIPLES','high','The Alchemical Queen is a personified principle grouped under the hub.'),
 ('ENT_ALC_REBIS','member_of','ENT_ALC_PRINCIPLES','high','The Rebis is a personified principle/goal-image grouped under the hub.'),
 ('ENT_ALC_AZOTH','member_of','ENT_ALC_PRINCIPLES','high','Azoth is a personified operative principle grouped under the hub.'),
 ('ENT_ALC_GREEN_LION','member_of','ENT_ALC_PRINCIPLES','high','The Green Lion is a personified emblem-principle grouped under the hub.'),
 ('ENT_ALC_KING','consort_of','ENT_ALC_QUEEN','high','Sol/Rex and Luna/Regina are the royal pair whose marriage is the chymical wedding.'),
 ('ENT_ALC_REBIS','child_of','ENT_ALC_KING','high','The Rebis is the hermaphroditic offspring born from the union of the King and Queen.'),
 ('ENT_ALC_REBIS','child_of','ENT_ALC_QUEEN','high','The Rebis is the hermaphroditic offspring of the King and Queen''s coniunctio.'),
 ('ENT_ALC_REBIS','embodies','ENT_ALC_PRINCIPLES','medium','As the coniunctio of opposites, the Rebis embodies the reconciliation of the alchemical principles.'),
 ('ENT_ALC_AZOTH','identified_with','ENT_ALC_MERCURY_PHIL','high','In the corpus Azoth is frequently identified with Philosophical Mercury as the universal transforming agent.'),
 ('ENT_ALC_KING','symbolizes','ENT_ALC_SULPHUR','medium','Sol/the King as the fixed solar masculine is read as the manifest form of the active Sulphur principle.'),
 ('ENT_ALC_QUEEN','symbolizes','ENT_ALC_MERCURY_PHIL','medium','Luna/the Queen as the volatile lunar feminine is aligned with the volatile Mercury principle.'),
 ('ENT_ALC_MERCURY_PHIL','reception_of','ENT_HER_TRISMEGISTUS','medium','Philosophical Mercury (Mercurius) draws its name and authority from the Hermetic tradition of Hermes Trismegistus, the legendary father of the art; a reception, not identity (homonym noted).'),
 ('ENT_ALC_PRINCIPLES','reception_of','ENT_HER_TRISMEGISTUS','medium','Western alchemy frames itself as the Hermetic art received from Hermes Trismegistus, whose Emerald Tablet underwrites its principles.'),
 ('ENT_ALC_PRINCIPLES','aligned_with','ENT_HER_WORLD_SOUL','medium','The animating spirit sought in the alchemical opus is aligned in the Hermetic-alchemical corpus with the World Soul / Anima Mundi as the universal life-principle.');
